declare module 'stockfish' {
  interface StockfishProcess {
    processCommand(command: string): void;
    terminate?: () => void;
  }

  function stockfish(variant: string, listener: (line: string) => void): StockfishProcess;
  export default stockfish;
}

// What: one Stockfish process speaking UCI inside a worker thread.
// Why: a search must not block the Electron main thread, and the lite build needs no cross-origin isolation.
// Removed: a position search would freeze the window, or the multi-thread build would fail to start.
import { parentPort } from 'node:worker_threads';
import stockfish from 'stockfish';

interface EvalRequest {
  type: 'eval';
  id: number;
  fen: string;
  depth: number;
}

interface Score {
  scoreCp?: number;
  mate?: number;
}

const pending: string[] = [];
let waiter: { test: (line: string) => boolean; resolve: (line: string) => void } | null = null;
let latest: Score = {};
let busy = false;

function onLine(line: string): void {
  const score = /(?:^|\s)score (cp|mate) (-?\d+)/.exec(line);
  if (score?.[1] === 'cp') latest = { scoreCp: Number(score[2]) };
  else if (score?.[1] === 'mate') latest = { mate: Number(score[2]) };
  if (waiter?.test(line)) {
    const resolve = waiter.resolve;
    waiter = null;
    resolve(line);
    return;
  }
  pending.push(line);
}

function waitFor(pattern: RegExp): Promise<string> {
  const index = pending.findIndex((line) => pattern.test(line));
  if (index >= 0) {
    const line = pending[index] ?? '';
    pending.splice(0, index + 1);
    return Promise.resolve(line);
  }
  return new Promise((resolve) => {
    waiter = { test: (line) => pattern.test(line), resolve };
  });
}

const engine = stockfish('lite-single', onLine);
let ready: Promise<void> | undefined;

function ensureReady(): Promise<void> {
  ready ??= (async () => {
    engine.processCommand('uci');
    await waitFor(/^uciok/);
    engine.processCommand('isready');
    await waitFor(/^readyok/);
  })();
  return ready;
}

parentPort?.on('message', (message: EvalRequest) => {
  if (message?.type !== 'eval') return;
  if (busy) {
    parentPort?.postMessage({ type: 'eval', id: message.id, failed: true, reason: 'busy' });
    return;
  }
  busy = true;
  void (async () => {
    await ensureReady();
    latest = {};
    engine.processCommand(`position fen ${message.fen}`);
    engine.processCommand(`go depth ${message.depth}`);
    const best = await waitFor(/^bestmove /);
    parentPort?.postMessage({
      type: 'eval',
      id: message.id,
      bestmove: best.split(/\s+/)[1] ?? '',
      scoreCp: latest.scoreCp,
      mate: latest.mate,
    });
  })()
    .catch((error: unknown) => {
      parentPort?.postMessage({
        type: 'eval',
        id: message.id,
        failed: true,
        reason: error instanceof Error ? error.message : 'engine',
      });
    })
    .finally(() => {
      busy = false;
    });
});

// What: queues FEN searches and marks a position failed instead of inventing a score.
// Why: centipawn loss needs an engine number, and a timeout must not become zero.
// Removed: a stalled search would hang the report, and a bad FEN would be scored anyway.
import path from 'node:path';
import { Worker } from 'node:worker_threads';
import { validateFen } from 'chess.js';

export const ENGINE_DEPTH = 8;
export const POSITION_TIMEOUT_MS = 5_000;
export const ENGINE_BUDGET_MS = 20 * 60 * 1000;

export interface PositionEval {
  fen: string;
  depth: number;
  evalFailed: boolean;
  scoreCp?: number;
  mate?: number;
  bestmove?: string;
  reason?: 'timeout' | 'fen' | 'engine' | 'budget';
}

export interface EngineOptions {
  depth?: number;
  timeoutMs?: number;
  budgetMs?: number;
  worker?: Worker;
}

interface WorkerEval {
  type?: string;
  id?: number;
  failed?: boolean;
  bestmove?: string;
  scoreCp?: number;
  mate?: number;
}

export function createEngine(options: EngineOptions = {}): {
  evaluate(fen: string): Promise<PositionEval>;
  close(): Promise<void>;
} {
  const depth = options.depth ?? ENGINE_DEPTH;
  const timeoutMs = options.timeoutMs ?? POSITION_TIMEOUT_MS;
  const budgetMs = options.budgetMs ?? ENGINE_BUDGET_MS;
  let worker = options.worker;
  const ownsWorker = options.worker === undefined;
  let startedAt: number | undefined;
  let queue: Promise<void> = Promise.resolve();
  let requestId = 0;

  function spawn(): Worker {
    return new Worker(path.join(__dirname, 'engine-worker.js'));
  }

  async function evaluate(fen: string): Promise<PositionEval> {
    const run = queue.then(() => evaluateOne(fen));
    queue = run.then(
      () => undefined,
      () => undefined,
    );
    return run;
  }

  async function evaluateOne(fen: string): Promise<PositionEval> {
    if (startedAt === undefined) startedAt = Date.now();
    if (Date.now() - startedAt >= budgetMs) {
      return { fen, depth, evalFailed: true, reason: 'budget' };
    }
    if (!validateFen(fen).ok) {
      return { fen, depth, evalFailed: true, reason: 'fen' };
    }
    worker ??= spawn();
    const current = worker;
    const id = (requestId += 1);

    return new Promise((resolve) => {
      let settled = false;
      const finish = (result: PositionEval): void => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        current.off('message', onMessage);
        resolve(result);
      };
      const timer = setTimeout(() => {
        finish({ fen, depth, evalFailed: true, reason: 'timeout' });
        if (worker === current) worker = undefined;
        void current.terminate();
      }, timeoutMs);
      const onMessage = (message: unknown): void => {
        if (!isWorkerEval(message) || message.id !== id) return;
        if (message.failed === true || (message.scoreCp === undefined && message.mate === undefined)) {
          finish({ fen, depth, evalFailed: true, reason: 'engine', bestmove: message.bestmove });
          return;
        }
        finish({
          fen,
          depth,
          evalFailed: false,
          scoreCp: message.scoreCp,
          mate: message.mate,
          bestmove: message.bestmove,
        });
      };
      current.on('message', onMessage);
      current.once('error', () => {
        if (worker === current) worker = undefined;
        finish({ fen, depth, evalFailed: true, reason: 'engine' });
      });
      current.postMessage({ type: 'eval', id, fen, depth });
    });
  }

  async function close(): Promise<void> {
    await queue;
    if (!ownsWorker || !worker) return;
    const current = worker;
    worker = undefined;
    await current.terminate();
  }

  return { evaluate, close };
}

function isWorkerEval(message: unknown): message is WorkerEval {
  return typeof message === 'object' && message !== null && (message as WorkerEval).type === 'eval';
}

// What: replays SAN moves into the FEN before and after each one.
// Why: the engine scores positions, and an illegal move must stop the line instead of inventing a board.
// Removed: a SAN-shaped but illegal move would be sent to Stockfish as a real position.
import { Chess } from 'chess.js';

export interface MovePosition {
  san: string;
  fenBefore: string;
  fenAfter?: string;
  illegal: boolean;
}

export function positionsFromMoves(sans: readonly string[]): MovePosition[] {
  const chess = new Chess();
  const positions: MovePosition[] = [];
  for (const san of sans) {
    const fenBefore = chess.fen();
    const played = chess.move(san);
    if (!played) {
      positions.push({ san, fenBefore, illegal: true });
      break;
    }
    positions.push({ san, fenBefore, fenAfter: played.after, illegal: false });
  }
  return positions;
}

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { positionsFromMoves } from './positions.js';

describe('positionsFromMoves', () => {
  it('records the board after a legal move', () => {
    const positions = positionsFromMoves(['e4']);
    assert.equal(positions.length, 1);
    assert.equal(positions[0]?.illegal, false);
    assert.equal(positions[0]?.fenAfter, 'rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR b KQkq e3 0 1');
  });

  it('stops at an illegal move and does not invent the next board', () => {
    const positions = positionsFromMoves(['e4', 'e4', 'Nf3']);
    assert.equal(positions.length, 2);
    assert.equal(positions[1]?.san, 'e4');
    assert.equal(positions[1]?.illegal, true);
    assert.equal(positions[1]?.fenAfter, undefined);
  });
});

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { Worker } from 'node:worker_threads';
import { Chess } from 'chess.js';
import { createEngine, ENGINE_DEPTH } from './engine.js';

const START_FEN = 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1';

function sixtyPositions(): string[] {
  const chess = new Chess();
  const fens: string[] = [];
  while (fens.length < 60) {
    if (chess.isGameOver()) chess.reset();
    const next = chess.moves()[0];
    if (!next) {
      chess.reset();
      continue;
    }
    chess.move(next);
    fens.push(chess.fen());
  }
  return fens;
}

describe('createEngine', () => {
  it('marks a bad FEN and a spent budget without a score', async () => {
    const invalid = createEngine();
    const bad = await invalid.evaluate('not-a-fen');
    await invalid.close();
    assert.equal(bad.evalFailed, true);
    assert.equal(bad.reason, 'fen');
    assert.equal(bad.scoreCp, undefined);

    const spent = createEngine({ budgetMs: 0 });
    const blocked = await spent.evaluate(START_FEN);
    await spent.close();
    assert.equal(blocked.evalFailed, true);
    assert.equal(blocked.reason, 'budget');
  });

  it('marks a search that does not answer as timed out', async () => {
    const worker = new Worker('setInterval(() => {}, 1000);', { eval: true });
    const engine = createEngine({ worker, timeoutMs: 40 });
    try {
      const result = await engine.evaluate(START_FEN);
      assert.equal(result.evalFailed, true);
      assert.equal(result.reason, 'timeout');
      assert.equal(result.scoreCp, undefined);
    } finally {
      await engine.close();
      await worker.terminate();
    }
  });

  it('scores the start and repeats that score', async () => {
    const engine = createEngine({ depth: ENGINE_DEPTH });
    try {
      const first = await engine.evaluate(START_FEN);
      const second = await engine.evaluate(START_FEN);
      assert.equal(first.evalFailed, false);
      assert.equal(first.depth, ENGINE_DEPTH);
      assert.equal(typeof first.scoreCp, 'number');
      assert.equal(first.scoreCp, second.scoreCp);
      assert.equal(first.bestmove, second.bestmove);
    } finally {
      await engine.close();
    }
  });

  it('evaluates 60 positions at depth 8 inside the proof bound', async () => {
    const engine = createEngine({ depth: ENGINE_DEPTH });
    const fens = sixtyPositions();
    try {
      await engine.evaluate(fens[0] ?? START_FEN);
      const samples: number[] = [];
      for (const fen of fens) {
        const started = process.hrtime.bigint();
        const result = await engine.evaluate(fen);
        samples.push(Number(process.hrtime.bigint() - started) / 1e6);
        assert.equal(result.evalFailed, false);
        assert.ok(result.scoreCp !== undefined || result.mate !== undefined);
      }
      const mean = samples.reduce((total, value) => total + value, 0) / samples.length;
      assert.ok(mean <= 150, `mean ${mean.toFixed(1)} ms`);
    } finally {
      await engine.close();
    }
  });
});

