// What: decides whether a pulse reading is settled or elevated.
// Why: every band is relative to this session's baseline, so the chart does not claim an absolute state.
// Removed: the same pulse would be called elevated for every player.
export const ELEVATED_MARGIN_BPM = 10;

export type PulseBand = 'settled' | 'elevated';

/** At or above baseline + 10 bpm is elevated. A non-number is not a band. */
export function bandFor(bpm: number, baselineBpm: number): PulseBand | null {
  if (!Number.isFinite(bpm) || !Number.isFinite(baselineBpm)) return null;
  return bpm >= baselineBpm + ELEVATED_MARGIN_BPM ? 'elevated' : 'settled';
}

// What: centipawn loss, per-move accuracy, band aggregates, and the verdict sentence.
// Why: those numbers are computed here, so a model cannot invent them.
// Removed: a failed search would count as a perfect move, and a thin band would print a percentage.
import { type PulseBand } from './bands.js';

/** Published Lichess curve: https://lichess.org/page/accuracy */
const WIN_PERCENT_K = 0.00368208;
const ACCURACY_A = 103.1668100711649;
const ACCURACY_K = 0.04354415386753951;
const ACCURACY_B = -3.166924740191411;
/** A blunder is a drop of at least 30 win-percent points. Lichess judgement 0.3. */
export const BLUNDER_WIN_DROP = 30;
/** Fewer scored moves than this are not given a percentage. Two is the checked thin case. */
export const MIN_BAND_MOVES = 5;

export interface Score {
  evalFailed: boolean;
  scoreCp?: number;
  mate?: number;
}

export interface MoveMetric {
  cpl: number | null;
  accuracy: number | null;
  blunder: boolean;
  band: PulseBand | null;
  includeInStats: boolean;
}

export type BandSummary =
  | { band: PulseBand; moves: number; status: 'insufficient' }
  | { band: PulseBand; moves: number; status: 'ok'; accuracy: number };

export interface AnalysisSummary {
  settled: BandSummary;
  elevated: BandSummary;
  blunders: number;
  elevatedBlunders: number;
}

export function centipawnLoss(before: Score, after: Score): number | null {
  if (!scored(before) || !scored(after)) return null;
  return Math.max(0, before.scoreCp + after.scoreCp);
}

export function winPercent(centipawns: number): number {
  return 100 / (1 + Math.exp(-WIN_PERCENT_K * centipawns));
}

/** `afterScoreCp` is the engine score after the move, from the opponent's point of view. */
export function moveAccuracy(beforeScoreCp: number, afterScoreCp: number): number {
  const before = winPercent(beforeScoreCp);
  const after = winPercent(-afterScoreCp);
  if (after >= before) return 100;
  const raw = ACCURACY_A * Math.exp(-ACCURACY_K * (before - after)) + ACCURACY_B + 1;
  return Math.min(100, Math.max(0, raw));
}

export function scoreMove(
  before: Score,
  after: Score,
  band: PulseBand | null,
  includeInStats: boolean,
): MoveMetric {
  const cpl = centipawnLoss(before, after);
  if (cpl === null || !scored(before) || !scored(after)) {
    return { cpl: null, accuracy: null, blunder: false, band, includeInStats };
  }
  const drop = winPercent(before.scoreCp) - winPercent(-after.scoreCp);
  return {
    cpl,
    accuracy: moveAccuracy(before.scoreCp, after.scoreCp),
    blunder: drop >= BLUNDER_WIN_DROP,
    band,
    includeInStats,
  };
}

export function analyseMoves(moves: readonly MoveMetric[]): AnalysisSummary {
  const counted = moves.filter((move) => move.includeInStats);
  return {
    settled: bandSummary('settled', counted),
    elevated: bandSummary('elevated', counted),
    blunders: counted.filter((move) => move.blunder).length,
    elevatedBlunders: counted.filter((move) => move.blunder && move.band === 'elevated').length,
  };
}

export function verdictLine(
  summary: AnalysisSummary,
  moment: { elevatedMinutes: number; deltaBpm: number; gapClause?: string },
): string {
  const blunderWord = summary.blunders === 1 ? 'blunder' : 'blunders';
  const where =
    moment.elevatedMinutes > 0
      ? `in the ${moment.elevatedMinutes} minutes your pulse stayed ${moment.deltaBpm} bpm above baseline`
      : 'while your pulse was elevated';
  const sentence = `${summary.blunders} ${blunderWord}, ${summary.elevatedBlunders} of them ${where}. ${accuracyPhrase(summary)}.`;
  const gap = moment.gapClause?.trim();
  return gap ? `${sentence} ${gap}` : sentence;
}

function bandSummary(band: PulseBand, moves: readonly MoveMetric[]): BandSummary {
  const scored = moves.filter((move) => move.band === band && move.accuracy !== null);
  if (scored.length < MIN_BAND_MOVES) {
    return { band, moves: scored.length, status: 'insufficient' };
  }
  const total = scored.reduce((sum, move) => sum + (move.accuracy ?? 0), 0);
  return { band, moves: scored.length, status: 'ok', accuracy: Math.round(total / scored.length) };
}

function accuracyPhrase(summary: AnalysisSummary): string {
  return `Accuracy ${bandPhrase('settled', summary.settled)}, ${bandPhrase('elevated', summary.elevated)}`;
}

function bandPhrase(label: string, summary: BandSummary): string {
  return summary.status === 'ok' ? `${summary.accuracy}% ${label}` : `${label} insufficient`;
}

function scored(score: Score): score is Score & { scoreCp: number } {
  return !score.evalFailed && score.mate === undefined && score.scoreCp !== undefined;
}

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { describe, it } from 'node:test';
import { bandFor } from './bands.js';
import { analyseMoves, scoreMove, verdictLine, type MoveMetric } from './metrics.js';

const ok = (scoreCp: number) => ({ evalFailed: false, scoreCp });
const failed = { evalFailed: true };

function counted(partial: Partial<MoveMetric> & Pick<MoveMetric, 'band'>): MoveMetric {
  return {
    cpl: partial.cpl ?? 0,
    accuracy: partial.accuracy ?? 80,
    blunder: partial.blunder ?? false,
    band: partial.band,
    includeInStats: partial.includeInStats ?? true,
  };
}

describe('bandFor', () => {
  it('shifts the same pulses when the baseline changes', () => {
    const pulses = [75, 85];
    assert.deepEqual(
      pulses.map((bpm) => bandFor(bpm, 70)),
      ['settled', 'elevated'],
    );
    assert.deepEqual(
      pulses.map((bpm) => bandFor(bpm, 80)),
      ['settled', 'settled'],
    );
    assert.equal(bandFor(80, 70), 'elevated');
    assert.equal(bandFor(Number.NaN, 70), null);
  });
});

describe('scoreMove', () => {
  it('keeps a preserved evaluation at zero loss and full accuracy', () => {
    const move = scoreMove(ok(40), ok(-40), 'settled', true);
    assert.equal(move.cpl, 0);
    assert.equal(move.accuracy, 100);
    assert.equal(move.blunder, false);
  });

  it('marks a large win-chance drop as a blunder and does not invent a mate loss', () => {
    const blunder = scoreMove(ok(0), ok(500), 'elevated', true);
    assert.equal(blunder.cpl, 500);
    assert.ok(blunder.accuracy !== null && Math.abs(blunder.accuracy - 19.062376700446695) < 1e-9);
    assert.equal(blunder.blunder, true);
    const mate = scoreMove({ evalFailed: false, mate: 1 }, ok(-100), 'settled', true);
    const missing = scoreMove(failed, ok(-20), 'settled', true);
    assert.equal(mate.cpl, null);
    assert.equal(mate.blunder, false);
    assert.equal(missing.cpl, null);
    assert.equal(missing.accuracy, null);
  });
});

describe('analyseMoves', () => {
  it('withholds a percentage when a band has two moves', () => {
    const summary = analyseMoves([
      counted({ band: 'elevated', accuracy: 40 }),
      counted({ band: 'elevated', accuracy: 50 }),
    ]);
    assert.deepEqual(summary.elevated, { band: 'elevated', moves: 2, status: 'insufficient' });
    assert.equal('accuracy' in summary.elevated, false);
  });

  it('rounds five settled moves and ignores an excluded blunder', () => {
    const summary = analyseMoves([
      counted({ band: 'settled', accuracy: 70 }),
      counted({ band: 'settled', accuracy: 70 }),
      counted({ band: 'settled', accuracy: 70 }),
      counted({ band: 'settled', accuracy: 70 }),
      counted({ band: 'settled', accuracy: 73, blunder: true }),
      counted({ band: 'elevated', accuracy: 10, blunder: true, includeInStats: false }),
    ]);
    assert.deepEqual(summary.settled, { band: 'settled', moves: 5, status: 'ok', accuracy: 71 });
    assert.equal(summary.blunders, 1);
    assert.equal(summary.elevatedBlunders, 0);
    assert.deepEqual(analyseMoves([
      counted({ band: 'settled', accuracy: 70 }),
      counted({ band: 'settled', accuracy: 70 }),
      counted({ band: 'settled', accuracy: 70 }),
      counted({ band: 'settled', accuracy: 70 }),
      counted({ band: 'settled', accuracy: 73, blunder: true }),
      counted({ band: 'elevated', accuracy: 10, blunder: true, includeInStats: false }),
    ]), summary);
  });
});

describe('verdictLine', () => {
  it('prints the template sentence and omits a percentage for a thin band', () => {
    const summary = analyseMoves([
      ...Array.from({ length: 5 }, () => counted({ band: 'settled', accuracy: 71 })),
      ...Array.from({ length: 5 }, () => counted({ band: 'elevated', accuracy: 54, blunder: true })),
      ...Array.from({ length: 3 }, () => counted({ band: 'settled', accuracy: 90, blunder: true })),
    ]);
    assert.equal(summary.blunders, 8);
    assert.equal(summary.elevatedBlunders, 5);
    assert.equal(
      verdictLine(summary, { elevatedMinutes: 11, deltaBpm: 18 }),
      '8 blunders, 5 of them in the 11 minutes your pulse stayed 18 bpm above baseline. Accuracy 71% settled, 54% elevated.',
    );
    const thin = analyseMoves([
      counted({ band: 'elevated', accuracy: 10, blunder: true }),
      counted({ band: 'elevated', accuracy: 20 }),
    ]);
    assert.equal(
      verdictLine(thin, {
        elevatedMinutes: 0,
        deltaBpm: 0,
        gapClause: 'Between games 2 and 3 you waited four minutes and never came down.',
      }),
      '1 blunder, 1 of them while your pulse was elevated. Accuracy settled insufficient, elevated insufficient. Between games 2 and 3 you waited four minutes and never came down.',
    );
  });

  it('does not import a model', () => {
    const source = readFileSync('src/main/analysis/metrics.ts', 'utf8');
    assert.equal(/from ['"][^'"]*ai/i.test(source), false);
    assert.equal(source.includes('openai'), false);
    assert.equal(source.includes('fetch('), false);
  });
});

